import React from 'react';
import './Projects.css';

function Projects() {
  const projects = [
    {
      id: 1,
      title: 'E-Commerce Platform',
      description: 'A full-stack e-commerce solution with React frontend and Node.js backend',
      tags: ['React', 'Node.js', 'MongoDB', 'Stripe'],
      link: '#'
    },
    {
      id: 2,
      title: 'Task Management App',
      description: 'Real-time collaborative task management application',
      tags: ['React', 'Firebase', 'Tailwind CSS'],
      link: '#'
    },
    {
      id: 3,
      title: 'Weather Dashboard',
      description: 'Interactive weather dashboard with real-time data visualization',
      tags: ['React', 'OpenWeather API', 'Chart.js'],
      link: '#'
    },
    {
      id: 4,
      title: 'Social Media Feed',
      description: 'Social platform with user interactions and real-time notifications',
      tags: ['React', 'GraphQL', 'PostgreSQL'],
      link: '#'
    },
    {
      id: 5,
      title: 'Blog Platform',
      description: 'CMS-like blog platform with markdown support',
      tags: ['Next.js', 'Prisma', 'PostgreSQL'],
      link: '#'
    },
    {
      id: 6,
      title: 'AI Chat Application',
      description: 'Intelligent chatbot with NLP capabilities',
      tags: ['React', 'Python', 'TensorFlow'],
      link: '#'
    }
  ];

  return (
    <section id="projects" className="projects">
      <div className="projects-container">
        <h2>Featured Projects</h2>
        <div className="projects-grid">
          {projects.map(project => (
            <div key={project.id} className="project-card">
              <h3>{project.title}</h3>
              <p>{project.description}</p>
              <div className="project-tags">
                {project.tags.map((tag, index) => (
                  <span key={index} className="tag">{tag}</span>
                ))}
              </div>
              <a href={project.link} className="project-link">View Project →</a>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default Projects;
